package com.bankingax.core.reservation;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
/** Agent only ranks Spring-filtered IDs. Any bad/failed response falls back to deterministic workload ordering. */
@Component @ConditionalOnProperty(name="app.reservation.ranking-provider",havingValue="http") public class HttpStaffRankingAdapter implements StaffRankingPort {
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build(); private final ObjectMapper json; private final String url; private final String token;
 public HttpStaffRankingAdapter(ObjectMapper j,@Value("${app.staff-agent-base-url:}")String u,@Value("${app.staff-agent-token:}")String t){json=j;url=u;token=t;}
 public List<Long> rank(List<Candidate> candidates,String task){List<Long> ids=candidates.stream().map(Candidate::staffId).toList();try{if(url.isBlank())return StaffRankingPort.byWorkload(candidates);var body=json.writeValueAsString(Map.of("candidateIds",ids,"candidates",candidates.stream().map(c->Map.of("staffId",c.staffId(),"activeAssignments",c.activeAssignments())).toList(),"taskCode",task));var r=http.send(HttpRequest.newBuilder(URI.create(url+"/api/v1/staff-ranking")).timeout(Duration.ofSeconds(3)).header("Content-Type","application/json").header("X-Staff-Agent-Token",token).POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)return StaffRankingPort.byWorkload(candidates);var out=json.readTree(r.body()).path("staffIds");List<Long> ranked=new ArrayList<>();for(var n:out)if(n.canConvertToLong()&&ids.contains(n.asLong())&&!ranked.contains(n.asLong()))ranked.add(n.asLong());return ranked.isEmpty()?StaffRankingPort.byWorkload(candidates):ranked;}catch(Exception ignored){return StaffRankingPort.byWorkload(candidates);}}
}
